CREATE FUNCTION vnext.check_registry() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE present boolean := false; BEGIN CASE NEW.entity_type WHEN 'claim' THEN SELECT EXISTS(SELECT 1 FROM vnext.claim_revision WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND task_id=NEW.task_id AND entity_id=NEW.entity_id AND revision=NEW.revision AND access_level=NEW.access_level) INTO present; WHEN 'artifact' THEN SELECT EXISTS(SELECT 1 FROM vnext.artifact WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND task_id=NEW.task_id AND entity_id=NEW.entity_id AND revision=NEW.revision AND access_level=NEW.access_level) INTO present; WHEN 'observation' THEN SELECT EXISTS(SELECT 1 FROM vnext.observation WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND task_id=NEW.task_id AND entity_id=NEW.entity_id AND revision=NEW.revision AND access_level=NEW.access_level) INTO present;
        ELSE present := false; END CASE;
        IF NOT present THEN RAISE EXCEPTION 'registry requires actual matching domain revision' USING ERRCODE='23503'; END IF;
        RETURN NULL; END $$

CREATE FUNCTION vnext.check_dependency() RETURNS trigger LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
        DECLARE cyclic boolean; BEGIN
        PERFORM 1 FROM vnext.task WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND task_id=NEW.task_id FOR UPDATE;
        WITH RECURSIVE reachable(id) AS (SELECT NEW.predecessor_id UNION SELECT d.predecessor_id FROM vnext.work_dependency d JOIN reachable r ON d.work_item_id=r.id WHERE d.tenant_id=NEW.tenant_id AND d.project_id=NEW.project_id AND d.task_id=NEW.task_id)
        SELECT EXISTS(SELECT 1 FROM reachable WHERE id=NEW.work_item_id) INTO cyclic;
        IF cyclic THEN RAISE EXCEPTION 'work dependency cycle' USING ERRCODE='23514'; END IF; RETURN NEW; END $$

CREATE FUNCTION vnext.check_publication_ref() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE a vnext.artifact%ROWTYPE; BEGIN
        SELECT * INTO a FROM vnext.artifact WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND task_id=NEW.task_id AND entity_id=NEW.artifact_id AND revision=NEW.artifact_revision FOR UPDATE;
        IF NOT FOUND OR a.state<>'sealed' THEN RAISE EXCEPTION 'publication requires a sealed artifact' USING ERRCODE='23503'; END IF;
        IF NEW.access_level<a.access_level THEN RAISE EXCEPTION 'publication access level too low' USING ERRCODE='23514'; END IF; RETURN NEW; END $$

CREATE OR REPLACE FUNCTION vnext.check_artifact_update() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        BEGIN
        IF OLD.state='staged' AND NEW.state='sealed' THEN
        PERFORM vnext.require_evidence_mutation(OLD.tenant_id,OLD.project_id,OLD.task_id,OLD.tool_attempt_id);
        END IF;
        IF (to_jsonb(NEW)-'state'-'body_removed') IS DISTINCT FROM (to_jsonb(OLD)-'state'-'body_removed') OR (NEW.body_removed AND NEW.state<>'tombstoned') OR (OLD.state='tombstoned' AND NOT (NEW.state='tombstoned' AND NOT OLD.body_removed AND NEW.body_removed)) OR (OLD.state='sealed' AND NEW.state<>'tombstoned') THEN
        RAISE EXCEPTION 'artifact metadata is immutable' USING ERRCODE='23514'; END IF;
        IF NEW.state='tombstoned' AND current_setting('wuji.gc',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'GC authority required' USING ERRCODE='42501'; END IF;
        IF NEW.state='tombstoned' AND OLD.state<>'tombstoned' AND vnext.artifact_retained(OLD.tenant_id,OLD.project_id,OLD.task_id,OLD.entity_id,OLD.revision) THEN
        RAISE EXCEPTION 'artifact is retained' USING ERRCODE='23514'; END IF; RETURN NEW; END $$

CREATE FUNCTION vnext.check_lease_mutation() RETURNS trigger
        LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE target vnext.artifact_lease%ROWTYPE; attempt text;
        BEGIN
        IF TG_OP='DELETE' THEN target:=OLD; ELSE target:=NEW; END IF;
        SELECT tool_attempt_id INTO attempt FROM vnext.artifact
            WHERE tenant_id=target.tenant_id AND project_id=target.project_id AND task_id=target.task_id
            AND entity_id=target.artifact_id AND revision=target.artifact_revision;
        IF NOT FOUND THEN RAISE EXCEPTION 'bound evidence authority required' USING ERRCODE='42501'; END IF;
        PERFORM vnext.require_evidence_mutation(target.tenant_id,target.project_id,target.task_id,attempt);
        IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
        END $$

CREATE FUNCTION vnext.require_artifact_mutation(t text,p text,k text,i text,v numeric) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE a vnext.artifact%ROWTYPE; BEGIN
        SELECT * INTO a FROM vnext.artifact WHERE tenant_id=t AND project_id=p AND task_id=k AND entity_id=i AND revision=v;
        IF NOT FOUND THEN RAISE EXCEPTION 'artifact absent' USING ERRCODE='42501'; END IF;
        IF a.agent_run_id IS NOT NULL THEN PERFORM vnext.require_model_mutation(t,p,k,a.agent_run_id,a.writer_subject);
        ELSE PERFORM vnext.require_evidence_mutation(t,p,k,a.tool_attempt_id); END IF; END $$

