CREATE FUNCTION vnext.check_artifact_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
        IF NEW.agent_run_id IS NOT NULL THEN PERFORM vnext.require_model_mutation(NEW.tenant_id,NEW.project_id,NEW.task_id,NEW.agent_run_id,NEW.writer_subject);
        ELSE PERFORM vnext.require_evidence_mutation(NEW.tenant_id,NEW.project_id,NEW.task_id,NEW.tool_attempt_id); END IF; RETURN NEW; END $$

CREATE FUNCTION vnext.claim_input_current(t text,p text,k text,c text,v numeric)
        RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
        DECLARE allowed_level integer;
        BEGIN
        IF NOT COALESCE(vnext.in_scope(t,p,k),false) THEN RETURN NULL; END IF;
        SELECT least(a.clearance,COALESCE(NULLIF(current_setting('wuji.clearance',true),'')::integer,-1))
        INTO allowed_level FROM vnext.task_access a WHERE a.tenant_id=t AND a.project_id=p AND a.task_id=k
        AND a.subject=current_setting('wuji.subject',true) AND a.can_read;
        IF allowed_level IS NULL OR NOT EXISTS(SELECT 1 FROM vnext.claim_revision x WHERE
            x.tenant_id=t AND x.project_id=p AND x.task_id=k AND x.entity_id=c AND x.revision=v
            AND x.access_level<=allowed_level) THEN RETURN NULL; END IF;
        RETURN NOT EXISTS(SELECT 1 FROM vnext.claim_revision x WHERE
            x.tenant_id=t AND x.project_id=p AND x.task_id=k AND x.entity_id=c AND x.revision>v);
        END $$

CREATE FUNCTION vnext.project_run_result(t text,p text,k text,r text,s text)
    RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
    DECLARE chosen text; status_value text; existing text; source_level integer;
    BEGIN
    IF NOT COALESCE(vnext.in_scope(t,p,k),false) THEN RAISE EXCEPTION 'result scope denied' USING ERRCODE='42501'; END IF;
    SELECT result_state INTO existing FROM vnext.agent_run WHERE tenant_id=t AND project_id=p AND task_id=k AND agent_run_id=r;
    IF NOT FOUND THEN RAISE EXCEPTION 'run absent' USING ERRCODE='42501'; END IF;
    IF s IS NOT NULL THEN
      PERFORM vnext.require_model_mutation(t,p,k,r,current_setting('wuji.subject',true));
      SELECT rs.access_level INTO source_level FROM vnext.result_submission rs WHERE tenant_id=t AND project_id=p AND task_id=k AND submission_id=s AND agent_run_id=r AND writer_subject=current_setting('wuji.subject',true);
      IF NOT FOUND OR NOT COALESCE(vnext.in_scope(t,p,k,source_level),false) THEN RAISE EXCEPTION 'matching submission required' USING ERRCODE='42501'; END IF;
      SELECT receipt_json::jsonb->>'status' INTO status_value FROM vnext.result_receipt WHERE tenant_id=t AND project_id=p AND task_id=k AND submission_id=s;
      status_value:=COALESCE(status_value,'received');
      IF status_value NOT IN ('received','accepted','rejected','historical_only') THEN RAISE EXCEPTION 'invalid result receipt' USING ERRCODE='23514'; END IF;
      IF existing='accepted' OR (status_value='received' AND existing NOT IN ('none','incomplete')) THEN RETURN existing; END IF;
      UPDATE vnext.agent_run SET result_state=status_value,result_submission_id=s WHERE tenant_id=t AND project_id=p AND task_id=k AND agent_run_id=r;
    ELSE
      IF current_setting('wuji.observe',true) IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'observer required' USING ERRCODE='42501'; END IF;
      UPDATE vnext.agent_run ar SET result_state='incomplete'
      WHERE ar.tenant_id=t AND ar.project_id=p AND ar.task_id=k AND ar.agent_run_id=r AND ar.result_state='none'
      AND ar.output_expectation='final_output' AND ar.process_state='exited' AND ar.stop_kind IN ('exited','environment_stopped')
      AND EXISTS(SELECT 1 FROM vnext.execution_observation e WHERE e.tenant_id=t AND e.project_id=p AND e.task_id=k AND e.agent_run_id=r AND e.receipt_id=ar.last_observation_id AND e.kind IN ('exited','environment_stopped'))
      AND EXISTS(SELECT 1 FROM vnext.run_operation_settlement x WHERE x.tenant_id=t AND x.project_id=p AND x.task_id=k AND x.agent_run_id=r AND x.status='settled')
      AND NOT EXISTS(SELECT 1 FROM vnext.resource_reservation x WHERE x.tenant_id=t AND x.project_id=p AND x.task_id=k AND x.agent_run_id=r AND x.state<>'released')
      AND NOT EXISTS(SELECT 1 FROM vnext.input_request i WHERE i.tenant_id=t AND i.project_id=p AND i.task_id=k AND i.work_item_id=ar.work_item_id AND i.status='pending')
      AND NOT EXISTS(SELECT 1 FROM vnext.result_submission x WHERE x.tenant_id=t AND x.project_id=p AND x.task_id=k AND x.agent_run_id=r);
    END IF;
    RETURN (SELECT result_state FROM vnext.agent_run WHERE tenant_id=t AND project_id=p AND task_id=k AND agent_run_id=r);
    END $$

CREATE FUNCTION vnext.guard_admission_counter_purpose()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE purpose text := current_setting('wuji.request_purpose',true);
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF NEW.model_attempts < OLD.model_attempts
             OR NEW.tool_attempts < OLD.tool_attempts
             OR NEW.output_bytes < OLD.output_bytes
             OR NEW.received_bytes < OLD.received_bytes
             OR NEW.retained_bytes < OLD.retained_bytes
             OR NEW.forwarded_bytes < OLD.forwarded_bytes THEN
            RAISE EXCEPTION 'admission counters cannot decrease' USING ERRCODE='42501';
          END IF;
          IF purpose='model_request' THEN
            IF ROW(NEW.tool_attempts,NEW.output_bytes,NEW.received_bytes,NEW.retained_bytes,NEW.forwarded_bytes)
               IS DISTINCT FROM
               ROW(OLD.tool_attempts,OLD.output_bytes,OLD.received_bytes,OLD.retained_bytes,OLD.forwarded_bytes) THEN
              RAISE EXCEPTION 'model request cannot mutate tool or output counters' USING ERRCODE='42501';
            END IF;
          ELSIF purpose='tool_request' THEN
            IF ROW(NEW.model_attempts,NEW.output_bytes,NEW.received_bytes,NEW.retained_bytes,NEW.forwarded_bytes)
               IS DISTINCT FROM
               ROW(OLD.model_attempts,OLD.output_bytes,OLD.received_bytes,OLD.retained_bytes,OLD.forwarded_bytes) THEN
              RAISE EXCEPTION 'tool request cannot mutate model or output counters' USING ERRCODE='42501';
            END IF;
          ELSIF purpose IN ('model_settle','tool_settle') THEN
            IF ROW(NEW.model_attempts,NEW.tool_attempts)
               IS DISTINCT FROM ROW(OLD.model_attempts,OLD.tool_attempts) THEN
              RAISE EXCEPTION 'settlement cannot mutate attempt counters' USING ERRCODE='42501';
            END IF;
          ELSE
            RAISE EXCEPTION 'request purpose required' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_admission_counter_insert()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF current_setting('wuji.request_purpose',true) NOT IN
             ('model_request','tool_request','model_settle','tool_settle')
             OR ROW(NEW.model_attempts,NEW.tool_attempts,NEW.output_bytes,
                    NEW.received_bytes,NEW.retained_bytes,NEW.forwarded_bytes)
                IS DISTINCT FROM ROW(0,0,0,0,0,0) THEN
            RAISE EXCEPTION 'admission counters must start at zero' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_tool_call_insert()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF current_setting('wuji.request_purpose',true)<>'tool_request'
             OR NEW.status NOT IN ('pending_approval','admitted')
             OR NEW.latest_attempt_id IS NOT NULL THEN
            RAISE EXCEPTION 'tool call must start as a proposal' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_resource_reservation_insert()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF current_setting('wuji.request_purpose',true)<>'tool_request'
             OR NEW.state<>'reserved'
             OR NULLIF(NEW.source_receipt_json::jsonb->>'tool_attempt_id','') IS NULL THEN
            RAISE EXCEPTION 'tool resource must start reserved for an attempt' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_run_settlement_insert()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE purpose text := current_setting('wuji.request_purpose',true);
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF purpose='tool_request' AND NEW.status<>'pending' THEN
            RAISE EXCEPTION 'tool request cannot insert a settled operation' USING ERRCODE='42501';
          ELSIF purpose NOT IN ('tool_request','tool_settle') THEN
            RAISE EXCEPTION 'tool settlement purpose required' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_model_call_purpose()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE purpose text := current_setting('wuji.request_purpose',true);
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
          IF purpose='model_request' THEN
            IF OLD.send_state<>'not_sent' OR NEW.send_state<>'sending'
               OR ROW(NEW.response_state,NEW.billing_state,NEW.local_state,NEW.inflight,
                      NEW.upstream_status,NEW.content_type,NEW.gateway_usage_ref,
                      NEW.gateway_spend_ref,NEW.response_available,NEW.received_bytes,
                      NEW.retained_bytes,NEW.forwarded_bytes,NEW.output_bytes,
                      NEW.settlement_json)
                  IS DISTINCT FROM
                  ROW(OLD.response_state,OLD.billing_state,OLD.local_state,OLD.inflight,
                      OLD.upstream_status,OLD.content_type,OLD.gateway_usage_ref,
                      OLD.gateway_spend_ref,OLD.response_available,OLD.received_bytes,
                      OLD.retained_bytes,OLD.forwarded_bytes,OLD.output_bytes,
                      OLD.settlement_json) THEN
              RAISE EXCEPTION 'model request cannot mutate settlement fields' USING ERRCODE='42501';
            END IF;
          ELSIF purpose='model_settle' THEN
            IF OLD.send_state='not_sent' AND NEW.send_state IS DISTINCT FROM OLD.send_state THEN
              RAISE EXCEPTION 'model settlement cannot cross the send fence' USING ERRCODE='42501';
            END IF;
          ELSE
            RAISE EXCEPTION 'model write purpose required' USING ERRCODE='42501';
          END IF;
          RETURN NEW;
        END $$

CREATE FUNCTION vnext.guard_tool_attempt_purpose()
        RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
        DECLARE purpose text := current_setting('wuji.request_purpose',true);
        BEGIN
          IF current_user=pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=TG_RELID)) THEN RETURN NEW; END IF;
