            IF OLD.status<>'admitted' OR NEW.status<>'dispatched'
               OR ROW(NEW.started_at,NEW.receipt_json,NEW.output,NEW.output_media_type,
                      NEW.output_completeness,NEW.capture_json,NEW.result_receipt_json,
